sec("Rules of the Air","Interception signals",[dzF("Your signals to the interceptor","<g class=\"pdg\"><rect x=\"10\" y=\"30\" width=\"170\" height=\"40\" fill=\"var(--mid)\" opacity=\".12\"/><path d=\"M10 30H180M10 70H180\" stroke=\"var(--mid)\" stroke-width=\"0.9\" fill=\"none\" stroke-dasharray=\"4 3\"/><text x=\"14\" y=\"26\" class=\"d2\">2,000 ft aal</text><text x=\"14\" y=\"80\" class=\"d2\">1,000 ft aal</text><rect x=\"40\" y=\"104\" width=\"110\" height=\"5\" fill=\"var(--rwy)\"/><path d=\"M10 109H180\" stroke=\"var(--ink-2)\" stroke-width=\"1\" fill=\"none\"/><g transform=\"translate(96 52) scale(-0.9 0.9)\"><path d=\"M16.6-6.7L27.4-15.8Q28.4-16.3 29.4-15.8L30.8-4Z\" fill=\"var(--accent)\"/><path d=\"M23.5-3.1L33.6-2.7Q34.3-2.2 33.6-1.8L23.5-1.4Z\" fill=\"var(--accent)\"/><path d=\"M-28.4-1.6C-28.4-3.2-27.5-4.2-26-4.5L-17-5.6L-13.4-6.1L-7.1-9.6C-5.6-10.1-3-10.2 0-10.2L6.5-10C8.5-9.8 9.8-9.1 11-8L27-4.6L31.6-3.8L31.7-2.6L26-1.6L12 0.6C5 1.8-2 2.6-8 2.8L-20 2.6C-24 2.4-26.5 1.6-27.5 0.6C-28.2 0-28.4-0.6-28.4-1.6Z\" fill=\"var(--accent)\"/><path d=\"M-28.3-3.3Q-31.6-1.6-28.3 0.1Z\" fill=\"var(--accent)\"/><path d=\"M-14.5 1.6Q-15.6 3.7-12.4 3.9L8.2 3.4Q10.2 3.1 10.2 1.6Z\" fill=\"var(--accent)\"/><path d=\"M-29.5-1.8L-27.3-10.5Q-26.7-11.1-26.8-10.2L-28.9-1.4ZM-29.3-1.4L-31.6 7.3Q-32.2 7.9-32.1 7L-30.1-1.8Z\" fill=\"var(--accent)\"/><path d=\"M-12.1-6.3L-7.3-9.1H-5.4V-6.3Z\" fill=\"var(--surface)\" opacity=\".85\"/><rect x=\"-4.2\" y=\"-9.1\" width=\"6\" height=\"2.8\" rx=\".6\" fill=\"var(--surface)\" opacity=\".85\"/><path d=\"M3-9.1H6.2C8-9 9-8.5 9.8-7.7L9.2-6.3H3Z\" fill=\"var(--surface)\" opacity=\".85\"/></g><path d=\"M62 50H40\" stroke=\"var(--accent)\" stroke-width=\"1\" fill=\"none\" stroke-dasharray=\"3 2\"/><path d=\"M136 50h14\" stroke=\"var(--accent)\" stroke-width=\"1.2\" fill=\"none\"/><path d=\"M0 0L-7.0 -3.5L-7.0 3.5Z\" fill=\"var(--accent)\" transform=\"translate(154 50) rotate(0)\"/><text x=\"190\" y=\"18\" class=\"d1\">\u201cAerodrome inadequate\u201d</text><text x=\"190\" y=\"31\" class=\"d2\">Raise gear if possible while</text><text x=\"190\" y=\"41\" class=\"d2\">passing over the runway between</text><text x=\"190\" y=\"51\" class=\"d2\">1,000 and 2,000 ft above</text><text x=\"190\" y=\"61\" class=\"d2\">aerodrome level, and keep circling.</text><path d=\"M8 122H312\" stroke=\"var(--ch-tx)\" stroke-width=\"0.8\" fill=\"none\" opacity=\".45\"/><text x=\"10\" y=\"142\" class=\"d1\">\u201cI cannot comply\u201d</text><text x=\"10\" y=\"153\" class=\"d2\">all lights on and off,</text><text x=\"10\" y=\"163\" class=\"d2\">regular intervals</text><rect x=\"122\" y=\"146\" width=\"10\" height=\"12\" rx=\"1.5\" fill=\"var(--mid)\"/><rect x=\"142\" y=\"146\" width=\"10\" height=\"12\" rx=\"1.5\" fill=\"var(--mid)\"/><rect x=\"162\" y=\"146\" width=\"10\" height=\"12\" rx=\"1.5\" fill=\"var(--mid)\"/><rect x=\"182\" y=\"146\" width=\"10\" height=\"12\" rx=\"1.5\" fill=\"var(--mid)\"/><rect x=\"202\" y=\"146\" width=\"10\" height=\"12\" rx=\"1.5\" fill=\"var(--mid)\"/><rect x=\"222\" y=\"146\" width=\"10\" height=\"12\" rx=\"1.5\" fill=\"var(--mid)\"/><rect x=\"242\" y=\"146\" width=\"10\" height=\"12\" rx=\"1.5\" fill=\"var(--mid)\"/><rect x=\"262\" y=\"146\" width=\"10\" height=\"12\" rx=\"1.5\" fill=\"var(--mid)\"/><rect x=\"282\" y=\"146\" width=\"10\" height=\"12\" rx=\"1.5\" fill=\"var(--mid)\"/><path d=\"M118 159H308\" stroke=\"var(--ink-2)\" stroke-width=\"0.8\" fill=\"none\"/><text x=\"10\" y=\"184\" class=\"d1\">\u201cI am in distress\u201d</text><text x=\"10\" y=\"195\" class=\"d2\">all lights on and off,</text><text x=\"10\" y=\"205\" class=\"d2\">irregular intervals</text><rect x=\"122\" y=\"188\" width=\"4\" height=\"12\" rx=\"1.5\" fill=\"var(--mid)\"/><rect x=\"132\" y=\"188\" width=\"14\" height=\"12\" rx=\"1.5\" fill=\"var(--mid)\"/><rect x=\"150\" y=\"188\" width=\"4\" height=\"12\" rx=\"1.5\" fill=\"var(--mid)\"/><rect x=\"172\" y=\"188\" width=\"8\" height=\"12\" rx=\"1.5\" fill=\"var(--mid)\"/><rect x=\"185\" y=\"188\" width=\"3\" height=\"12\" rx=\"1.5\" fill=\"var(--mid)\"/><rect x=\"192\" y=\"188\" width=\"16\" height=\"12\" rx=\"1.5\" fill=\"var(--mid)\"/><rect x=\"220\" y=\"188\" width=\"5\" height=\"12\" rx=\"1.5\" fill=\"var(--mid)\"/><rect x=\"233\" y=\"188\" width=\"9\" height=\"12\" rx=\"1.5\" fill=\"var(--mid)\"/><rect x=\"245\" y=\"188\" width=\"4\" height=\"12\" rx=\"1.5\" fill=\"var(--mid)\"/><path d=\"M118 201H308\" stroke=\"var(--ink-2)\" stroke-width=\"0.8\" fill=\"none\"/><text x=\"122\" y=\"214\" class=\"d2\">time</text><path d=\"M0 0L-6 -3L-6 3Z\" fill=\"var(--ink-2)\" transform=\"translate(306 201) rotate(0)\"/><rect x=\"10\" y=\"222\" width=\"300\" height=\"22\" rx=\"6\" fill=\"var(--surface)\" stroke=\"var(--line)\" stroke-width=\"1\"/><text x=\"160\" y=\"236\" class=\"d2\" text-anchor=\"middle\">The interceptor answers both with a break-away climbing turn: \u201cunderstood\u201d.</text></g>","\u201cCannot comply\u201d must look different from ordinary flashing lights, so switch every light fully on and off.",320,252)]);
